exactHeadsTypeScript:
function exactHeads(value: unknown, code: string, allowEmpty = false): Readonly<Record<string, string>> {
  const source = record(value, code);
  const keys = Object.keys(source);
  if ((!allowEmpty && keys.length === 0) || keys.some((key, index) => index > 0 && keys[index - 1]!.localeCompare(key) >= 0)) fail(code);
  return freeze(Object.fromEntries(keys.map((key) => [token(key, code), digest(source[key], code)])));
}

sortedHeadsTypeScript:
function sortedHeads(value: Readonly<Record<string, string>>): Readonly<Record<string, string>> {
  return freeze(Object.fromEntries(Object.entries(value).sort(([left], [right]) => left.localeCompare(right))));
}
